.agent-messages { display: flex; flex-direction: column; gap: 26px; }
.agent-user-message { align-self: flex-end; max-width: 90%; background: var(--accent); color: var(--foreground); border: 1px solid var(--border); border-radius: 14px 14px 3px; padding: 12px 15px; font-size: 13px; line-height: 1.6; white-space: pre-wrap; overflow-wrap: anywhere; }
.agent-answer { font-size: 13px; }
