.agent-metrics { display: grid; grid-template-columns: repeat(3, minmax(0px, 1fr)); gap: 8px; margin-top: 17px; }
.agent-metrics > div { padding: 12px 10px; border: 1px solid var(--result-border); border-radius: 8px; background: var(--result-background); }
.agent-metrics strong { display: block; font-size: 24px; font-weight: 600; line-height: 1.2; color: var(--result-foreground); }
.agent-metrics span { display: block; color: var(--muted-foreground); font-size: 10px; margin-top: 7px; line-height: 1.5; }
.agent-patients { margin-top: 16px; border: 1px solid var(--border); border-radius: 9px; overflow: hidden; }
.agent-patients button { display: flex; justify-content: space-between; align-items: center; text-align: left; width: 100%; padding: 12px; gap: 12px; background: var(--card); }
.agent-patients button + button { border-top: 1px solid var(--border); }
.agent-patients button:hover { background: var(--accent); }
.agent-patients b { display: block; color: var(--text-primary); font-size: 12px; font-weight: 600; }
.agent-patients small { display: block; margin-top: 4px; font-size: 10px; color: var(--muted-foreground); line-height: 1.6; }
.agent-patients svg { flex-shrink: 0; color: var(--text-primary); }
.agent-view-results { width: 100%; margin-top: 10px; height: auto; min-height: 35px; font-size: 11px; white-space: normal; }
.agent-source { display: flex; align-items: center; gap: 5px; color: var(--muted-foreground); font-size: 10px; line-height: 1.5; margin-top: 14px; }
.agent-thinking { display: flex; gap: 8px; align-items: center; color: var(--text-primary); font-size: 12px; margin-top: 24px; }
.agent-next-questions { display: flex; flex-wrap: wrap; gap: 7px; margin-top: 22px; padding-top: 18px; border-top: 1px solid var(--border); }
.agent-next-questions button { display: flex; align-items: center; gap: 6px; padding: 7px 10px; border: 1px solid var(--border); border-radius: 7px; text-align: left; font-size: 11px; line-height: 1.5; color: var(--text-primary); background: var(--card); }
.agent-next-questions button:hover { background: var(--accent); }
.agent-next-questions svg { flex-shrink: 0; }
.agent-composer { padding: 16px 20px max(16px, env(safe-area-inset-bottom)); border-top: 1px solid var(--border); background: var(--card); }
.agent-input-box {
  border: 1px solid var(--input); border-radius: 12px; padding: 4px; box-shadow: 0 2px 8px var(--foreground);
  @supports (color: color-mix(in lab, red, red)) {
  box-shadow: 0 2px 8px color-mix(in srgb, var(--foreground) 3%, transparent);
}
}
.agent-input-box:focus-within {
  outline: 2px solid var(--ring);
  @supports (color: color-mix(in lab, red, red)) {
  outline: 2px solid color-mix(in srgb, var(--ring) 40%, transparent);
}
  border-color: var(--ring);
}
.agent-input-box textarea { border: 0px; box-shadow: none; outline: none; resize: none; min-height: 58px; max-height: 140px; overflow-y: auto; font-size: 13px; background: transparent; }
.agent-input-box textarea:focus-visible { border: 0px; box-shadow: none; }
.agent-input-actions { display: flex; justify-content: space-between; align-items: center; gap: 10px; padding: 2px 4px 4px 8px; }
.agent-input-actions > span { font-size: 9px; color: var(--muted-foreground); }
.agent-composer > p { text-align: center; color: var(--muted-foreground); font-size: 10px; margin-top: 10px; }
.agent-filter { max-width: 360px; color: var(--text-primary); }
.agent-filter span { overflow: hidden; text-overflow: ellipsis; }
.agent-panel button:focus-visible { outline: 2px solid var(--ring); outline-offset: 3px; }
@media (max-width: 480px) {
  .agent-header { padding: 16px; gap: 8px; }
