  .agent-welcome h2 { font-size: 26px; }
  .agent-composer { padding: 12px; }
  .agent-input-box textarea { font-size: 16px; }
}
@media (prefers-reduced-motion: reduce) {
  .agent-panel, .agent-panel *, .agent-launch { animation: auto ease 0s 1 normal none running none !important; transition: none !important; }
}
.prior-history .history-item { padding-top: 18px; }
.prior-history .history-item:not(:last-child)::after { content: ""; position: absolute; left: 3px; top: 32px; bottom: -10px; width: 1px; background: var(--border); }
.prior-history .prior-study-card { border: 1px solid var(--border); border-radius: 9px; padding: 14px; background: var(--card); }
.prior-study-heading { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; justify-content: space-between; margin-bottom: 12px; }
.prior-study-heading > span { font-size: 8px; letter-spacing: 0.06em; color: var(--muted-foreground); background: var(--muted); padding: 3px 5px; border-radius: 3px; }
.prior-history .history-item p { color: var(--muted-foreground); line-height: 1.65; }
.prior-pacs-label { display: flex; align-items: center; gap: 6px; font-size: 11px; color: var(--muted-foreground); }
.study-findings { display: grid; grid-template-columns: repeat(2, minmax(0px, 1fr)); gap: 10px; padding-top: 4px; }
.study-finding > span { display: block; color: var(--muted-foreground); font-size: 10px; margin-bottom: 4px; }
.study-finding > strong { display: flex; align-items: center; gap: 4px; color: var(--result-foreground); font-size: 11px; font-weight: 550; }
.prior-history .prior-open-results { width: 100%; color: var(--text-primary); }
.prior-open-results > svg:last-child { margin-left: auto; }
.prior-results-dialog[data-slot="dialog-content"] { width: min(900px, -32px + 100vw); max-width: 900px; max-height: calc(100dvh - 48px); overflow-y: auto; padding: 26px; gap: 16px; }
.prior-results-dialog [data-slot="dialog-header"] { padding-right: 22px; }
.prior-results-dialog [data-slot="dialog-title"] { font-size: 21px; font-weight: 600; }
.prior-results-dialog [data-slot="dialog-description"] { font-size: 12px; }
.prior-results-provenance { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; font-size: 11px; color: var(--action-success-foreground); }
.prior-results-provenance > span { margin-left: auto; color: var(--muted-foreground); }
.prior-report-fields { display: grid; grid-template-columns: 1fr 1.6fr 1fr; gap: 16px; padding: 15px; background: var(--muted); border: 1px solid var(--border); border-radius: 8px; }
.prior-report-fields dt { color: var(--muted-foreground); font-size: 10px; margin-bottom: 4px; }
.prior-report-fields dd { font-size: 12px; font-variant-numeric: tabular-nums; }
.prior-report-tabs { gap: 16px; }
.prior-report-summary { display: grid; gap: 18px; }
.prior-report-result-grid { display: grid; grid-template-columns: repeat(2, minmax(0px, 1fr)); gap: 14px; }
.prior-report-result { background: var(--result-background); border: 1px solid var(--result-border); border-radius: 8px; padding: 16px; }
.prior-report-result .study-finding > span { font-size: 12px; }
.prior-report-result .study-finding > strong { font-size: 17px; }
.prior-report-result > p { margin-top: 12px; color: var(--muted-foreground); font-size: 12px; }
.prior-report-result .echo-score { margin-top: 12px; }
.prior-evidence-layout { display: grid; grid-template-columns: minmax(0px, 0.85fr) minmax(0px, 1.4fr); gap: 18px; align-items: start; }
.prior-clip-section h3 { display: flex; align-items: center; gap: 8px; font-size: 13px; font-weight: 600; }
.prior-clip-section h3 > span { font-size: 10px; padding: 2px 5px; background: var(--muted); border-radius: 3px; }
.prior-clip-section > p { font-size: 10px; color: var(--muted-foreground); margin: 8px 0px 14px; }
.prior-clip { padding: 12px; border: 1px solid var(--border); border-radius: 8px; margin-bottom: 12px; }
.prior-clip img { width: 100%; max-height: 130px; object-fit: contain; background: black; border-radius: 5px; margin-bottom: 10px; }
.prior-clip b { font-size: 11px; }
.prior-clip .echo-score { margin-top: 8px; }
@media (max-width: 640px) {
  .prior-results-dialog[data-slot="dialog-content"] { padding: 20px; }
  .prior-evidence-layout, .prior-report-result-grid { grid-template-columns: 1fr; }
  .prior-report-fields { grid-template-columns: 1fr 1fr; }
  .prior-report-fields > div:nth-child(2) { grid-area: 2 / 1 / auto / -1; }
}








